  dewar:    { n: "Сосуд с жидким азотом", d: "Сосуд Дьюара, над горлышком стелется холодный пар. Прикасаться без перчаток нельзя.", a: [["listen", "Послушать, как кипит азот", { t: "Азот тихо шипит и булькает, пар стелется по полу.", neuro: -5 }]] },
  xray:     { n: "Рентгеновский аппарат", d: "Аппарат на штативе с тубусом. Панель ещё включается.", a: [["mirror", "Сделать себе снимок", { rad: 1 }]] },
  lightbox: { n: "Негатоскоп", d: "Светящийся экран, на нём прикреплены рентгеновские снимки.", a: [["read", "Попросить «Эхо» описать снимки", { pool: "xrays" }]] },
  trays:    { n: "Ванночки с проявителем", d: "Ванночки с проявителем и закрепителем, щипцы, в одной — недопроявленный снимок.", a: [["read", "Вынуть снимок из ванночки", { pool: "photos" }]] },
  redlamp:  { n: "Красная лампа", d: "Красный фонарь фотолаборатории. Включается щелчком.", a: [["listen", "Щёлкнуть выключателем", { t: "Щёлк. Лампа гудит красным. «Эхо» отмечает: свет здесь никому больше не нужен.", neuro: -5 }]] },
  screens:  { n: "Экраны", d: "Экраны с графиками и столбцами цифр: машины продолжают считать, хотя смотреть некому.", a: [["read", "Попросить «Эхо» прочитать экраны", { pool: "screens" }]] },

  /* ── охрана и проходная ── */
