  frame:    { n: "Рамка досмотра", d: "Арка металлодетектора с табло. Она всё ещё пищит, если пройти с оружием.", a: [["scan", "Пройти через рамку", {}], ["salvage", "Снять плату рамки", { parts: { chip: 1, wire: 1 } }]] },
  monitors: { n: "Мониторы наблюдения", d: "Ряд мониторов с картинками камер: коридоры, двери, лестница. Половина экранов показывает снег.", a: [["cams", "Посмотреть мониторы", {}]] },
  gunrack:  { n: "Оружейная стойка", d: "Стойка с гнёздами под стволы. Большинство гнёзд пусты, под стойкой — ящик для батарей.", a: [["search", "Проверить стойку и ящик", { tag: "arms" }]] },
  targets:  { n: "Мишени", d: "Мишени на тросах в конце тира, табло попаданий и пульт протяжки.", a: [["aim", "Пострелять по мишеням: заряд оружия на тренировку", {}]] },
