  hangers:  { n: "Вешалки со спецовками", d: "Брезентовые куртки, комбинезоны и сапоги на крюках. Карманы оттопырены.", a: [["search", "Пошарить по карманам спецовок", { tag: "pockets" }], ["strip", "Снять с вешалки комбинезон", {}]] },

  /* ── техника ── */
  forklift: { n: "Погрузчик", d: "Электропогрузчик с поднятыми вилами. Ключ в замке, аккумулятор под сиденьем.", a: [["listen", "Нажать на клаксон", { t: "Клаксон гудит на весь склад. Где-то в ответ что-то лязгнуло.", noise: 9 }], ["salvage", "Снять аккумулятор погрузчика", { parts: { cell: 2, scrap: 1 } }]] },
