  robotwreck:{ n: "Разобранный робот", d: "Робот на столе с открытым кожухом: провода торчат, одна рука снята. Индикатор мигает очень слабо.", a: [["salvage", "Разобрать робота на детали", { parts: { chip: 1, servo: 1, optic: 1 }, risk: "spark" }]] },
  press:    { n: "Пресс", d: "Гидравлический пресс со столом для пластин. Масляный, но рабочий.", a: [["plate", "Выправить бронепластину: четыре металлолома, матрицы хватит на две", {}]] },
  generator:{ n: "Генератор", d: "Генератор гудит ровно, стрелки приборов дрожат у красной черты.", a: [["read", "Снять показания приборов", { pool: "gauges" }], ["salvage", "Снять запасной конденсатор", { parts: { cap: 2 }, risk: "shock" }]] },
  transformer:{ n: "Трансформатор", d: "Трансформатор за сеткой, над ним потрескивают разряды. Табличка: «Не влезай — убьёт».", a: [["salvage", "Срезать кусок обмотки", { parts: { wire: 2, magnet: 1 }, risk: "shock" }]] },
  cables:   { n: "Пучки кабелей", d: "Кабели вдоль стены, перетянутые хомутами. Некоторые обрезаны и висят.", a: [["salvage", "Срезать обрывки провода", { parts: { wire: 2 }, risk: "shock" }]] },
  gauges:   { n: "Приборы", d: "Панель с приборами: стрелки, лампочки, тумблеры с подписями.", a: [["read", "Снять показания", { pool: "gauges" }]] },
  valves:   { n: "Вентили", d: "Вентили и задвижки на трубах, у каждого — бирка с номером. Один пропускает: шипит.", a: [["vent", "Перекрыть пропускающий вентиль", {}]] },
  vent:     { n: "Вытяжка", d: "Решётка вытяжки и выключатель на стене. Мотор цел, просто его выключили.", a: [["vent", "Включить вытяжку", {}]] },
