  scheme:   { n: "Схема этажа на стене", d: "Схема этажа под стеклом: помещения, коридоры, двери, пути эвакуации. «Эхо» может её считать.", a: [["map", "Изучить схему: карта этажа в «Эхо»", {}]] },
  projector:{ n: "Проектор", d: "Проектор под потолком с пультом на столе. В нём — недосмотренная презентация.", a: [["read", "Включить проектор", { pool: "slides_p" }]] },
  copier:   { n: "Копировальный аппарат", d: "Аппарат гудит, в лотке застрял лист. Индикатор мигает: «Замятие бумаги».", a: [["read", "Вытащить застрявший лист", { pool: "copier" }]] },
