  complaints:{ n: "Ящик для жалоб", d: "Ящик, набитый жалобами до отказа: листки торчат из щели.", a: [["read", "Вытащить жалобу и прочитать", { pool: "complaints" }]] },
  lanterns: { n: "Фонари", d: "Фонари на полках, без огня. Один тихо гудит, хотя света от него нет.", a: [["salvage", "Вынуть батарею из фонаря", { parts: { cell: 1 } }], ["listen", "Послушать гудящий фонарь", { t: "Гудит ровно, на одной ноте. Похоже, он светит в каком-то другом свете.", neuro: -5 }]] },
  lamprack: { n: "Стойка шахтёрских ламп", d: "Ряды ламп-коногонок на зарядке и крючки с номерками. Не хватает четырёх ламп.", a: [["salvage", "Снять аккумулятор лампы", { parts: { cell: 1 } }], ["read", "Прочитать номерки", { pool: "tags" }]] },
