  cores:    { n: "Керны", d: "Столбики породы в ящиках, метр за метром глубины. Некоторые тихо поют.", a: [["listen", "Прислониться ухом к керну", { t: "Керн звучит низко, ровно — как будто под землёй кто-то держит одну ноту.", neuro: -8 }], ["search", "Перебрать ящики с кернами", { tag: "ore" }]] },
  toolwall: { n: "Стена с инструментами", d: "Инструменты на щите, каждый в своём контуре. Нескольких не хватает.", a: [["search", "Снять с щита годный инструмент", { tag: "tools" }]] },
