/* Что поставить в помещение этого вида: до трёх вещей — о чём описание говорит первым
   (3.2: в нижних глубинах — больше, max). */
LAB.FIX.forRoom = function (type, r, max) {
  var def = LAB.ROOMS[type]; if (!def || def.special) return [];
  var text = ((def.n || "") + ". " + (def.desc || "")).toLowerCase(), hits = [];
  RULES.forEach(function (ru) { var m = ru[0].exec(text); if (m && T[ru[1]] && hits.every(function (h) { return h.id !== ru[1]; })) hits.push({ id: ru[1], at: m.index }); });
  hits.sort(function (a, b) { return a.at - b.at; });
  var out = hits.slice(0, max || 3).map(function (h) { return h.id; });
  if (!out.length) out.push(r && r.chance(0.5) ? "table" : "chair");
  return out;
};
